import * as React from "react";

export type MarqueeBulbsIconProps = React.SVGProps<SVGSVGElement> & { size?: number };

export function MarqueeBulbsIcon({ size = 20, ...props }: MarqueeBulbsIconProps) {
  return (
    <svg
      width={size}
      height={size}
      viewBox="0 0 24 24"
      fill="none"
      stroke="currentColor"
      strokeWidth="1.8"
      strokeLinecap="round"
      strokeLinejoin="round"
      aria-hidden="true"
      {...props}
    >
      <rect x="6" y="8" width="12" height="8" rx="1" /><circle cx="6" cy="8" r="1" /><circle cx="12" cy="5.5" r="1" /><circle cx="18" cy="8" r="1" />
    </svg>
  );
}
